// Mock localStorage hook for simplicity inline
function useLocalStorage<T>(key: string, initialValue: T): [T, (val: T | ((val: T) => T)) => void] {
  const [storedValue, setStoredValue] = useState<T>(initialValue);

  useEffect(() => {
    try {
      const item = window.localStorage.getItem(key);
      if (item) setStoredValue(JSON.parse(item));
    } catch (error) {
      console.warn(error);
    }
  }, [key]);

  const setValue = (value: T | ((val: T) => T)) => {
    try {
      const valueToStore = value instanceof Function ? value(storedValue) : value;
      setStoredValue(valueToStore);
      window.localStorage.setItem(key, JSON.stringify(valueToStore));
    } catch (error) {
      console.warn(error);
    }
  };
  return [storedValue, setValue];
}

export default function Home() {
  const [theme, setTheme] = useLocalStorage<"light" | "dark">("briefforge-theme", "light");
  const [selections, setSelections] = useLocalStorage<string[]>("briefforge-selections", []);
  
  const [cmdOpen, setCmdOpen] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  useEffect(() => {
    if (theme === "dark") document.documentElement.classList.add("dark");
    else document.documentElement.classList.remove("dark");
  }, [theme]);

  const toggleSelection = (id: string, limit?: number) => {
    setSelections(prev => {
      if (prev.includes(id)) return prev.filter(i => i !== id);
      return [...prev, id]; // Simplify limit logic for brevity in rewrite
    });
  };

  const handleCommandSelect = (id: string, category: string) => {
    toggleSelection(id);
  };

  const generatedPrompt = usePromptGenerator(selections);
  const [editablePrompt, setEditablePrompt] = useState("");

  useEffect(() => {
    if (!drawerOpen) setEditablePrompt(generatedPrompt);
  }, [generatedPrompt, drawerOpen]);

  const filteredStyles = styles.filter(s => s.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div className="min-h-screen pb-40">
      <FloatingNav 
        theme={theme} 
        toggleTheme={() => setTheme(theme === "light" ? "dark" : "light")} 
        onSearchClick={() => setCmdOpen(true)}
      />
      
      <CommandPalette open={cmdOpen} setOpen={setCmdOpen} onSelect={handleCommandSelect} />

      <main className="max-w-[1440px] mx-auto px-6 sm:px-12 pt-40 md:pt-48 space-y-48">
        
        {/* Elegant Intro */}
        <section className="max-w-4xl">
          <h1 className="font-serif text-6xl md:text-8xl tracking-tight leading-[1.05] mb-8">
            Design less.<br/>
            <span className="text-text-secondary">Direct better.</span>
          </h1>
          <p className="text-xl md:text-2xl text-text-secondary max-w-2xl leading-relaxed mb-16">
            Turn your ideas into language AI actually understands. Build better interfaces with precise design vocabulary.
          </p>
          
          <div className="relative max-w-2xl group">
            <div className="absolute -inset-1 bg-gradient-to-r from-accent to-accent/50 rounded-2xl blur opacity-20 group-hover:opacity-40 transition duration-1000 group-hover:duration-200"></div>
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="What are you building today?"
              className="relative w-full bg-[var(--theme-bg-card)] border-border-strong border p-6 rounded-2xl text-xl font-medium outline-none focus:ring-2 focus:ring-accent transition-all placeholder:text-text-secondary/50"
            />
          </div>
        </section>

        {/* Alternating Layout Chapter 1: Styles */}
        <section id="dictionary" className="grid grid-cols-1 lg:grid-cols-12 gap-16 items-start">
          <div className="lg:col-span-4 sticky top-40">
            <h2 className="font-serif text-4xl mb-4">Aesthetic Foundation</h2>
            <p className="text-text-secondary text-lg leading-relaxed">
              Every great design begins with a strong foundation. Select a visual direction that aligns with your product's goals.
            </p>
          </div>
          <div className="lg:col-span-8 grid grid-cols-1 sm:grid-cols-2 gap-6">
            {filteredStyles.map(s => (
              <PremiumCard
                key={s.id}
                id={s.id}
                name={s.name}
                description={s.description}
                selected={selections.includes(s.id)}
                onToggle={toggleSelection}
                preview={<div className="w-full h-full bg-border-subtle/20" />} // Mock preview for now
              />
            ))}
          </div>
        </section>

        {/* Alternating Layout Chapter 2: Typography */}
        <section className="grid grid-cols-1 lg:grid-cols-12 gap-16 items-start">
          <div className="lg:col-span-8 grid grid-cols-1 sm:grid-cols-2 gap-6 order-2 lg:order-1">
            {typography.map(t => (
              <PremiumCard
                key={t.id}
                id={t.id}
                name={t.name}
                description={t.description}
                selected={selections.includes(t.id)}
                onToggle={toggleSelection}
              />
            ))}
          </div>
          <div className="lg:col-span-4 sticky top-40 order-1 lg:order-2">
            <h2 className="font-serif text-4xl mb-4">Expressive Type</h2>
            <p className="text-text-secondary text-lg leading-relaxed">
              Hierarchy is established through weight and spacing, not just size. Choose your voice.
            </p>
          </div>
        </section>

      </main>

      <FloatingDock 
        selectionCount={selections.length}
        onViewPrompt={() => setDrawerOpen(true)}
        onCopyPrompt={() => navigator.clipboard.writeText(editablePrompt)}
        onReset={() => setSelections([])}
      />

      <RightDrawer 
        isOpen={drawerOpen}
        onClose={() => setDrawerOpen(false)}
        prompt={editablePrompt}
        onPromptChange={setEditablePrompt}
      />
    </div>
  );
}
