"use client";

import { cn } from "@/lib/utils";
import { Check } from "lucide-react";
import { motion } from "framer-motion";
import { VisualPreview } from "./VisualPreview";

interface PremiumCardProps {
  id: string;
  name: string;
  description?: string;
  selected?: boolean;
  onToggle: (id: string) => void;
  category?: string;
  showPreview?: boolean;
}

export function PremiumCard({
  id,
  name,
  description,
  selected,
  onToggle,
  category,
  showPreview,
}: PremiumCardProps) {
  return (
    <motion.button
      whileHover={{ y: -4 }}
      whileTap={{ scale: 0.98 }}
      transition={{ duration: 0.15, ease: "easeOut" }}
      onClick={() => onToggle(id)}
      className={cn(
        "group relative flex flex-col items-start w-full text-left p-6 rounded-[18px] border transition-colors duration-200 cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--theme-bg-main)] overflow-hidden",
        selected
          ? "bg-[var(--theme-bg-card)] border-accent shadow-[inset_0_1px_0_0_rgba(255,255,255,0.05),_0_0_20px_rgba(91,108,255,0.15)] ring-1 ring-accent"
          : "bg-[var(--theme-bg-card)] border-border-subtle hover:border-border-strong hover:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.02),_0_8px_30px_rgba(0,0,0,0.04)]"
      )}
      aria-pressed={selected}
    >
      {/* Selected checkmark */}
      {selected && (
        <motion.div
          initial={{ scale: 0, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ duration: 0.2 }}
          className="absolute top-4 right-4 w-6 h-6 rounded-full bg-accent text-white flex items-center justify-center z-10"
        >
          <Check className="w-3.5 h-3.5 stroke-[3]" />
        </motion.div>
      )}

      {/* Preview Area */}
      {showPreview && (
        <div className="w-full aspect-[4/3] rounded-xl overflow-hidden mb-6 bg-[var(--theme-bg-main)] relative group-hover:scale-[1.02] transition-transform duration-200 border border-border-subtle">
          <VisualPreview id={id} category={category} />
        </div>
      )}

      {/* Content */}
      <div className="flex flex-col gap-1.5 transition-transform duration-200 group-hover:translate-x-0.5">
        <h3 className="font-sans font-medium text-text-primary text-lg tracking-tight">
          {name}
        </h3>
        {description && (
          <p className="font-sans text-sm text-text-secondary leading-relaxed opacity-100 group-hover:opacity-80 transition-opacity duration-200">
            {description}
          </p>
        )}
      </div>
    </motion.button>
  );
}
