"use client";

import { useEffect, useState } from "react";
import { Command } from "cmdk";
import { Search, Sparkles, BookOpen, Layers } from "lucide-react";
import { cn } from "@/lib/utils";

interface CommandPaletteProps {
  open: boolean;
  setOpen: (open: boolean) => void;
  onSelect: (id: string, category: string) => void;
}

export function CommandPalette({ open, setOpen, onSelect }: CommandPaletteProps) {
  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === "k" && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        setOpen(true);
      }
    };
    document.addEventListener("keydown", down);
    return () => document.removeEventListener("keydown", down);
  }, [setOpen]);

  return (
    <Command.Dialog
      open={open}
      onOpenChange={setOpen}
      label="Global Command Menu"
      className={cn(
        "fixed inset-0 z-[100] flex items-start justify-center pt-[15vh] sm:pt-[20vh]",
        "bg-black/40 backdrop-blur-sm"
      )}
    >
      <div className="w-full max-w-xl mx-4 overflow-hidden bg-[var(--theme-bg-card)] rounded-2xl shadow-2xl border border-border-subtle flex flex-col">
        <div className="flex items-center px-4 border-b border-border-subtle" cmdk-input-wrapper="">
          <Search className="w-5 h-5 text-text-secondary mr-2" />
          <Command.Input
            autoFocus
            placeholder="Search commands, styles, recipes..."
            className="flex-1 h-14 bg-transparent outline-none placeholder:text-text-secondary text-text-primary text-lg"
          />
        </div>
        <Command.List className="max-h-[60vh] overflow-y-auto p-2 no-scrollbar">
          <Command.Empty className="py-6 text-center text-text-secondary">
            No results found.
          </Command.Empty>

          <Command.Group heading="Suggestions" className="px-2 py-2 text-xs font-medium text-text-secondary">
            <Command.Item 
              onSelect={() => { onSelect('y2k', 'style'); setOpen(false); }}
              className="flex items-center px-3 py-3 mt-1 rounded-xl cursor-pointer aria-selected:bg-bg-main aria-selected:text-text-primary text-text-secondary transition-colors"
            >
              <Sparkles className="w-4 h-4 mr-3" />
              Y2K Style
            </Command.Item>
            <Command.Item 
              onSelect={() => { onSelect('bauhaus', 'style'); setOpen(false); }}
              className="flex items-center px-3 py-3 mt-1 rounded-xl cursor-pointer aria-selected:bg-bg-main aria-selected:text-text-primary text-text-secondary transition-colors"
            >
              <Layers className="w-4 h-4 mr-3" />
              Bauhaus
            </Command.Item>
            <Command.Item 
              onSelect={() => { onSelect('recipe-1', 'recipe'); setOpen(false); }}
              className="flex items-center px-3 py-3 mt-1 rounded-xl cursor-pointer aria-selected:bg-bg-main aria-selected:text-text-primary text-text-secondary transition-colors"
            >
              <BookOpen className="w-4 h-4 mr-3" />
              SaaS Landing Page Recipe
            </Command.Item>
          </Command.Group>
        </Command.List>
      </div>
    </Command.Dialog>
  );
}
