"use client";

import { motion } from "framer-motion";

export function VisualPreview({ id, category }: { id: string; category?: string }) {
  // We hash the ID to get some pseudo-randomness for the abstract shapes
  const hash = id.split("").reduce((acc, char) => acc + char.charCodeAt(0), 0);
  
  // Choose abstract visual based on category or hash
  if (id === "glassmorphism") {
    return (
      <div className="w-full h-full bg-gradient-to-br from-blue-500/20 to-purple-500/20 flex items-center justify-center p-4 relative overflow-hidden">
        <div className="absolute inset-0 bg-white/5 backdrop-blur-md" />
        <motion.div 
          className="w-16 h-16 rounded-2xl bg-white/20 backdrop-blur-xl border border-white/40 shadow-[0_8px_32px_rgba(0,0,0,0.1)] relative z-10"
          animate={{ y: [-2, 2, -2] }}
          transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
        />
        <div className="absolute -top-4 -right-4 w-24 h-24 bg-blue-500/30 rounded-full blur-xl" />
        <div className="absolute -bottom-4 -left-4 w-24 h-24 bg-purple-500/30 rounded-full blur-xl" />
      </div>
    );
  }
  
  if (id === "neobrutalism") {
    return (
      <div className="w-full h-full bg-[#FFE55C] flex items-center justify-center p-4">
        <motion.div 
          className="w-16 h-16 bg-[#FF6B6B] border-[3px] border-black shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]"
          whileHover={{ x: 2, y: 2, boxShadow: "2px 2px 0px 0px rgba(0,0,0,1)" }}
        />
      </div>
    );
  }

  if (id === "swiss") {
    return (
      <div className="w-full h-full bg-[#E5E5E5] grid grid-cols-3 grid-rows-3 gap-1 p-4">
        <div className="col-span-2 row-span-2 bg-[#FF3B30]" />
        <div className="bg-black" />
        <div className="col-span-1 row-span-1 bg-black" />
        <div className="col-span-3 bg-white" />
      </div>
    );
  }
  
  // Generic abstract geometric representations for everything else
  const colors = [
    ["from-accent/20 to-accent/5", "bg-accent/40"],
    ["from-success/20 to-success/5", "bg-success/40"],
    ["from-warning/20 to-warning/5", "bg-warning/40"],
    ["from-purple-500/20 to-purple-500/5", "bg-purple-500/40"],
  ];
  
  const [bgGrad, shapeColor] = colors[hash % colors.length];
  const shapeType = hash % 3;

  return (
    <div className={`w-full h-full bg-gradient-to-br ${bgGrad} flex items-center justify-center p-4 relative overflow-hidden`}>
      <motion.div
        className={`${shapeColor} backdrop-blur-sm border border-white/10 dark:border-white/5 ${
          shapeType === 0 ? "w-12 h-12 rounded-full" : 
          shapeType === 1 ? "w-14 h-14 rounded-2xl rotate-12" : 
          "w-16 h-8 rounded-full -rotate-12"
        }`}
        animate={{ scale: [0.95, 1.05, 0.95] }}
        transition={{ duration: 4, repeat: Infinity, ease: "easeInOut", delay: (hash % 5) * 0.2 }}
      />
      <div className="absolute inset-0 bg-[url('data:image/svg+xml,%3Csvg viewBox=%220 0 200 200%22 xmlns=%22http://www.w3.org/2000/svg%22%3E%3Cfilter id=%22noise%22%3E%3CfeTurbulence type=%22fractalNoise%22 baseFrequency=%220.8%22 numOctaves=%223%22 stitchTiles=%22stitch%22/%3E%3C/filter%3E%3Crect width=%22100%25%22 height=%22100%25%22 filter=%22url(%23noise)%22 opacity=%220.03%22/%3E%3C/svg%3E')]" />
    </div>
  );
}
