"use client";

import { useEffect, useState } from "react";
import { motion, useScroll, useMotionValueEvent } from "framer-motion";
import { Search, Moon, Sun, Terminal } from "lucide-react";
import { cn } from "@/lib/utils";

interface FloatingNavProps {
  onSearchClick: () => void;
  theme: "light" | "dark";
  toggleTheme: () => void;
}

export function FloatingNav({ onSearchClick, theme, toggleTheme }: FloatingNavProps) {
  const { scrollY } = useScroll();
  const [isScrolled, setIsScrolled] = useState(false);

  useMotionValueEvent(scrollY, "change", (latest) => {
    setIsScrolled(latest > 50);
  });

  return (
    <motion.nav
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
      className="fixed top-0 left-0 right-0 z-50 flex justify-center px-4 pt-6"
    >
      <motion.div
        layout
        transition={{ duration: 0.2 }}
        className={cn(
          "flex items-center justify-between gap-6 px-4 py-3 bg-[var(--theme-bg-card)]/70 backdrop-blur-xl border border-border-subtle rounded-2xl shadow-sm overflow-hidden w-full transition-all duration-300",
          isScrolled ? "max-w-4xl shadow-md py-2" : "max-w-6xl"
        )}
      >
        <div className="flex items-center gap-2 font-serif font-medium tracking-tight">
          <Terminal className="w-5 h-5 text-accent" />
          <span>BriefForge</span>
        </div>

        <div className="hidden md:flex items-center gap-6 font-sans text-sm font-medium text-text-secondary">
          <a href="#dictionary" className="hover:text-text-primary transition-colors">Dictionary</a>
          <a href="#recipes" className="hover:text-text-primary transition-colors">Recipes</a>
          <a href="#resources" className="hover:text-text-primary transition-colors">Resources</a>
          <a href="#playbooks" className="hover:text-text-primary transition-colors">Playbooks</a>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={onSearchClick}
            className="flex items-center gap-2 px-3 py-1.5 bg-bg-main hover:bg-border-subtle text-text-secondary hover:text-text-primary transition-colors rounded-lg text-sm border border-border-subtle font-sans"
            aria-label="Search"
          >
            <Search className="w-4 h-4" />
            <span className="hidden sm:inline">Search...</span>
            <kbd className="hidden sm:inline-flex items-center gap-1 font-mono text-[10px] bg-[var(--theme-bg-card)] px-1.5 py-0.5 rounded ml-2 border border-border-subtle">
              <span className="text-xs">⌘</span>K
            </kbd>
          </button>
          
          <button
            onClick={toggleTheme}
            className="p-2 text-text-secondary hover:text-text-primary hover:bg-bg-main transition-colors rounded-lg"
            aria-label="Toggle theme"
          >
            {theme === "light" ? <Moon className="w-4 h-4" /> : <Sun className="w-4 h-4" />}
          </button>
        </div>
      </motion.div>
    </motion.nav>
  );
}
