"use client";

import { motion } from "framer-motion";
import { Copy, RefreshCw, Eye, Download } from "lucide-react";
import { cn } from "@/lib/utils";

interface FloatingDockProps {
  selectionCount: number;
  onViewPrompt: () => void;
  onCopyPrompt: () => void;
  onReset: () => void;
}

export function FloatingDock({ selectionCount, onViewPrompt, onCopyPrompt, onReset }: FloatingDockProps) {
  return (
    <div className="fixed bottom-8 left-0 right-0 z-40 pointer-events-none flex justify-center px-4">
      <motion.div 
        initial={{ y: 100, opacity: 0 }}
        animate={{ y: selectionCount > 0 ? 0 : 100, opacity: selectionCount > 0 ? 1 : 0 }}
        transition={{ duration: 0.4, type: "spring", bounce: 0 }}
        className="pointer-events-auto flex items-center gap-1 p-2 bg-[var(--theme-bg-card)]/80 backdrop-blur-2xl border border-border-subtle rounded-full shadow-2xl"
      >
        <div className="flex items-center gap-3 pl-4 pr-3 py-2 border-r border-border-subtle">
          <div className="bg-accent text-white w-7 h-7 rounded-full flex items-center justify-center font-sans text-sm font-semibold">
            {selectionCount}
          </div>
          <span className="font-medium text-sm pr-2 text-text-primary hidden sm:block">
            {selectionCount === 1 ? "Item" : "Items"}
          </span>
        </div>

        <DockButton icon={<Eye className="w-5 h-5" />} label="Preview" onClick={onViewPrompt} />
        <DockButton icon={<Copy className="w-5 h-5" />} label="Copy" onClick={onCopyPrompt} />
        <DockButton icon={<Download className="w-5 h-5" />} label="Export" onClick={() => {}} />
        <div className="w-[1px] h-8 bg-border-subtle mx-1" />
        <DockButton icon={<RefreshCw className="w-5 h-5" />} label="Reset" onClick={onReset} danger />
      </motion.div>
    </div>
  );
}

function DockButton({ icon, label, onClick, danger }: { icon: React.ReactNode, label: string, onClick: () => void, danger?: boolean }) {
  return (
    <div className="relative group">
      <button 
        onClick={onClick}
        className={cn(
          "w-12 h-12 flex items-center justify-center rounded-full transition-colors",
          danger ? "text-text-secondary hover:text-error hover:bg-error/10" : "text-text-secondary hover:text-text-primary hover:bg-border-subtle/50"
        )}
        aria-label={label}
      >
        {icon}
      </button>
      
      {/* Tooltip */}
      <div className="absolute -top-10 left-1/2 -translate-x-1/2 px-3 py-1.5 bg-text-primary text-[var(--theme-bg-main)] text-xs font-medium rounded-lg opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none whitespace-nowrap">
        {label}
        <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-2 h-2 bg-text-primary rotate-45" />
      </div>
    </div>
  );
}
